mapper.select:
SELECT T1.CASH_ID ,T1.EXERCISE_TYPE ,T1.VDATE ,T1.MDATE ,T1.EXERCISE_DATE
,T1.ACT_EXERCISE_DATE
,T1.EXERCISE_PRICE ,T1.EXERCISE_REMARK ,T1.FINPROD_ID ,T1.FINPROD_TYPE ,T1.FINPROD_TYPE2 ,T1.BRANCH ,CASE WHEN ( SELECT count( * ) count FROM TRD_PRODUCT_DEAL T3
T3.SETTLE_DATE = T1.ACT_EXERCISE_DATE
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND (T3.PS = #{psT03,jdbcType=VARCHAR} or T3.PS = #{psT39,jdbcType=VARCHAR})
) > 0 THEN '${execType02}' ELSE '${execType01}' END AS EXERCISE_STATUS
FROM FIN_EXERCISE_PLAN T1 inner JOIN FIN_CASH_INFO T2 ON T1.CASH_ID = T2.CASH_ID AND T1.FINPROD_ID=T2.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EXERCISE_DATE asc
